// 埋め込み用の最小版（ECS command 上書きは 8192 バイト上限）。説明は repair-env-b.js を参照。
// 引数は REPAIR_ARGS 環境変数で渡す。node -e に --flag を渡すと node のオプションと解釈されるため。
const { PrismaClient } = require('@prisma/client');
const A = (process.env.REPAIR_ARGS || '').split(/\s+/).filter(Boolean);
const has = (n) => A.indexOf(n) >= 0;
const arg = (n) => {
  const h = A.find((v) => v.indexOf(n + '=') === 0);
  return h ? h.slice(n.length + 1) : null;
};
const p = new PrismaClient();
const q = (s, ...v) => p.$queryRawUnsafe(s, ...v);
const x = (s, ...v) => p.$executeRawUnsafe(s, ...v);

(async () => {
  try {
    console.log('== MIGRATIONS ==');
    for (const r of await q(
      'SELECT migration_name AS n, finished_at AS f, rolled_back_at AS r FROM _prisma_migrations ORDER BY started_at DESC LIMIT 6',
    )) {
      console.log(' ', r.n, r.r ? 'ROLLED_BACK' : r.f ? 'ok' : '*** FAILED ***');
    }
    const pw = await q(
      "SELECT column_name AS c FROM information_schema.columns WHERE table_name='users' AND column_name IN ('user_password_plain','user_password_encrypted')",
    );
    console.log('  users pw column:', pw.map((r) => r.c).join(',') || '(none)');

    console.log('== DUPS ==');
    const dups = await q(
      "SELECT customer_corporate_number AS n, COUNT(*)::int AS c FROM customers WHERE customer_corporate_number IS NOT NULL AND customer_corporate_number <> '' GROUP BY 1 HAVING COUNT(*) > 1",
    );
    if (!dups.length) console.log('  none');
    for (const d of dups) {
      console.log(' ', d.n, 'x' + d.c);
      for (const r of await q(
        'SELECT id, customer_name AS nm FROM customers WHERE customer_corporate_number = $1 ORDER BY id',
        d.n,
      )) {
        console.log('    id=' + r.id, r.nm);
      }
    }

    if (has('fix-duplicates')) {
      const b = await x("UPDATE customers SET customer_corporate_number = NULL WHERE customer_corporate_number = ''");
      const n = await x(
        'UPDATE customers SET customer_corporate_number = NULL WHERE customer_corporate_number IS NOT NULL AND id NOT IN (SELECT MIN(id) FROM customers WHERE customer_corporate_number IS NOT NULL GROUP BY customer_corporate_number)',
      );
      console.log('== FIX DUPS == blank:' + b, 'dups:' + n, '(no customer rows deleted)');
    }

    // 平文カラムを改名して暗号化カラムに合わせる。発行パスワードの値はそのまま残り、
    // 起動時の encrypt-existing-passwords.js が暗号化し直す。DROP を避けるのが要点。
    if (has('rename-pw')) {
      const c = await q(
        "SELECT column_name AS c FROM information_schema.columns WHERE table_name='users' AND column_name='user_password_plain'",
      );
      if (c.length) {
        await x('ALTER TABLE users RENAME COLUMN user_password_plain TO user_password_encrypted');
        await x('ALTER TABLE users ALTER COLUMN user_password_encrypted TYPE VARCHAR(512)');
        console.log('== RENAME PW == done (values preserved)');
      } else {
        console.log('== RENAME PW == skip (user_password_plain not found)');
      }
    }

    // Prisma 上は Json 非null（@default("{}")）。DB に NULL が残っていると読み取りで落ちる。
    if (has('backfill-json')) {
      const c = await x("UPDATE customers SET customer_custom_data = '{}' WHERE customer_custom_data IS NULL");
      const t = await x("UPDATE partners SET partner_custom_data = '{}' WHERE partner_custom_data IS NULL");
      console.log('== BACKFILL JSON == customers:' + c, 'partners:' + t);
    }

    if (has('diff') || has('apply-diff')) {
      const { execFileSync } = require('child_process');
      const sql = execFileSync(
        'node',
        [
          './node_modules/prisma/build/index.js',
          'migrate',
          'diff',
          '--from-schema-datasource',
          'prisma/schema.prisma',
          '--to-schema-datamodel',
          'prisma/schema.prisma',
          '--script',
        ],
        { encoding: 'utf8', cwd: '/app' },
      );
      console.log('== DIFF ==');
      console.log(sql);
      const bad = /\b(DROP|TRUNCATE|DELETE)\b/i.test(sql);
      console.log('  destructive:', bad ? 'YES *** not applying ***' : 'no');
      if (has('apply-diff')) {
        if (bad) console.log('  破壊的な文があるため適用しません');
        else {
          for (const s of sql.split(';').map((v) => v.trim()).filter(Boolean)) await x(s);
          console.log('  applied');
        }
      }
    }

    const a = arg('activate');
    if (a) console.log('== ACTIVATE ==', a, await x('UPDATE users SET user_is_active = true WHERE user_email = $1', a));

    const sph = arg('set-password-hash');
    if (sph) {
      const i = sph.indexOf(':');
      const n = await x('UPDATE users SET user_password_hash = $1 WHERE user_email = $2', sph.slice(i + 1), sph.slice(0, i));
      console.log('== SET PW ==', sph.slice(0, i), 'rows=' + n);
    }

    // 実際に落ちていた2本を Prisma モデル経由で流す。生SQLでは列の取りこぼしを再現できない。
    if (has('verify')) {
      console.log('== VERIFY ==');
      const em = arg('email');
      if (!em) {
        console.log('  auth query: skip (--email=<アドレス> を指定)');
      } else {
        try {
          const u = await p.user.findUnique({
            where: { userEmail: em },
            include: {
              businessAssignments: { include: { business: true }, where: { business: { businessIsActive: true } } },
            },
          });
          console.log('  auth query(' + em + '):', u ? 'OK active=' + u.userIsActive + ' biz=' + u.businessAssignments.length : 'user not found');
        } catch (e) {
          console.log('  auth query: FAILED', e.message.split('\n').slice(-2).join(' '));
        }
      }
      try {
        const r = await p.project.findMany({ take: 1 });
        console.log('  project list:', 'OK rows=' + r.length);
      } catch (e) {
        console.log('  project list: FAILED', e.message.split('\n').slice(-2).join(' '));
      }
      try {
        const l = await p.partnerBusinessLink.findMany({ take: 1 });
        console.log('  partner link:', 'OK rows=' + l.length);
      } catch (e) {
        console.log('  partner link: FAILED', e.message.split('\n').slice(-2).join(' '));
      }
    }

    console.log('== USERS ==');
    for (const u of await q(
      'SELECT id, user_email AS em, user_name AS nm, user_role AS ro, user_is_active AS act FROM users ORDER BY id',
    )) {
      console.log(' id=' + u.id, u.em, '(' + u.nm + ')', u.ro, 'active=' + u.act);
    }
  } catch (e) {
    console.log('ERROR:', e.message);
    process.exitCode = 1;
  } finally {
    await p.$disconnect();
  }
})();
